          CLOUDFLARE_ACCOUNT_ID: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}
          CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_KV_API_TOKEN }}
          CONTRIBUTORS_KV_NAMESPACE_ID: ${{ secrets.CONTRIBUTORS_KV_NAMESPACE_ID }}
        run: bun run scripts/sync-contributors.ts

|
            const url = `${{ steps.deploy.outputs.deployment-url }}`;
            const sha = context.payload.pull_request.head.sha.slice(0, 7);
            const marker = '<!-- cf-workers-preview -->';
            const body = [
